	privileges.global.rescind(['groups:view:users'], 'guests', (err) => {
		assert.ifError(err);
		request(`${nconf.get('url')}/api/user/foo`, { json: true }, (err, res, body) => {
			assert.ifError(err);
			assert.equal(res.statusCode, 401);
			assert.deepEqual(body, {
				response: {},
				status: {
					code: 'not-authorised',
